<?php
defined('ABSPATH')||exit; class CFP_Webhooks{public function send(int $id,array $payload):void{global $wpdb; $row=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".CFP_Database::table('webhooks')." WHERE id=%d AND status=%s",$id,'active'),ARRAY_A); if(!$row) return; $cfg=json_decode($row['config']?:'{}',true); $url=esc_url_raw($cfg['url']??''); if(!CFP_Security::valid_url($url)) return; $body=wp_json_encode($payload); $sig=hash_hmac('sha256',$body,(string)($cfg['secret']??'')); $res=wp_remote_post($url,array('timeout'=>10,'headers'=>array('Content-Type'=>'application/json','X-CFP-Signature'=>$sig),'body'=>$body)); (new CFP_Webhook_Logger())->log($id,is_wp_error($res)?'failed':'sent',$res);}}
